"""Spawn the child under a real PTY and send a real Ctrl-C (0x03),
exactly like an interactive keyboard interrupt would."""
import os, pty, time, sys, select

CHILD = sys.argv[1]

def main():
    pid, fd = pty.fork()
    if pid == 0:
        # child: exec python on the target script
        os.execvp("python3", ["python3", "-u", CHILD])
        os._exit(127)
    # parent
    # give the child time to start all tasks
    deadline = time.time() + 1.2
    buf = b""
    while time.time() < deadline:
        r, _, _ = select.select([fd], [], [], 0.1)
        if fd in r:
            try:
                buf += os.read(fd, 4096)
            except OSError:
                break
    # send Ctrl-C (ETX)
    os.write(fd, b"\x03")
    # drain remaining output
    end = time.time() + 5
    while time.time() < end:
        r, _, _ = select.select([fd], [], [], 0.2)
        if fd in r:
            try:
                data = os.read(fd, 4096)
            except OSError:
                break
            if not data:
                break
            buf += data
        else:
            # check if child exited
            wpid, status = os.waitpid(pid, os.WNOHANG)
            if wpid:
                break
    try:
        _, status = os.waitpid(pid, 0)
    except ChildProcessError:
        status = 0
    sys.stdout.write(buf.decode(errors="replace"))
    sys.stdout.flush()

main()
